#!/usr/bin/env node
/**
 * Icon sprite builder — the master sprite for this repo.
 * Reads every .svg in SRC_DIR (underscore-prefixed files skipped) and
 * writes a <symbol> sprite to OUT_FILE. Reference icons via
 * <use href="/path/to/icons.svg#name"/>.
 *
 * The three symbol-assembly helpers are exported because sprite-builder.js
 * (the consumer-facing `bd-sprite` CLI) builds subset sprites from the same
 * sources and must produce byte-equivalent symbols — a second copy of this
 * logic would drift.
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const SRC_DIR = path.join(ROOT, "assets", "images", "svg-icons");
const OUT_FILE = path.join(ROOT, "dist", "icons.svg");

function extractInner(svgString) {
  const match = svgString.match(/<svg[^>]*>([\s\S]*)<\/svg>/);
  if (!match) throw new Error("could not find <svg>...</svg> in source");
  return match[1].trim();
}

function extractViewBox(svgString) {
  const match = svgString.match(/viewBox="([^"]+)"/);
  return match ? match[1] : "0 0 24 24";
}

// Figma exports carry internal ids (clipPath/gradient/mask defs like
// "clip0_14540_880") referenced via url(#id) and href="#id". Concatenated
// into one sprite, ids collide and browsers resolve url(#id) to the FIRST
// match document-wide, so later icons pick up the wrong clip. Prefix every
// id (and its references) with the icon name.
function namespaceIds(inner, prefix) {
  const ids = new Set();
  const idRe = /\sid="([^"]+)"/g;
  let m;
  while ((m = idRe.exec(inner))) ids.add(m[1]);
  let out = inner;
  for (const id of ids) {
    const safe = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const ns = `${prefix}-${id}`;
    out = out
      .replace(new RegExp(`id="${safe}"`, "g"), `id="${ns}"`)
      .replace(new RegExp(`url\\(#${safe}\\)`, "g"), `url(#${ns})`)
      .replace(new RegExp(`href="#${safe}"`, "g"), `href="#${ns}"`);
  }
  return out;
}

function buildSprite() {
  if (!fs.existsSync(SRC_DIR)) {
    console.error(`source directory not found: ${SRC_DIR}`);
    process.exit(1);
  }
  const files = fs.readdirSync(SRC_DIR)
    .filter((f) => f.endsWith(".svg") && !f.startsWith("_"))
    .sort();
  if (files.length === 0) {
    console.error(`no .svg files found in ${SRC_DIR}`);
    process.exit(1);
  }
  fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
  const symbols = files.map((file) => {
    const name = path.basename(file, ".svg");
    const source = fs.readFileSync(path.join(SRC_DIR, file), "utf8");
    const viewBox = extractViewBox(source);
    const inner = namespaceIds(extractInner(source), name);
    // fill="none" reproduces the source icons' root <svg fill="none">
    // context: painted paths carry explicit fill="currentColor", but
    // stroke-only shapes (e.g. icon.svg) would otherwise default to a
    // black fill inside a <symbol>.
    return `  <symbol id="${name}" viewBox="${viewBox}" fill="none">${inner}</symbol>`;
  });
  const sprite = [
    `<?xml version="1.0" encoding="UTF-8"?>`,
    `<!-- Generated by scripts/build-icon-sprite.js. Do not edit. -->`,
    `<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">`,
    ...symbols,
    `</svg>`,
    ``,
  ].join("\n");
  fs.writeFileSync(OUT_FILE, sprite);
  console.log(`wrote ${files.length} symbols to ${path.relative(ROOT, OUT_FILE)}`);
}

function main() {
  try {
    buildSprite();
  } catch (err) {
    console.error(`sprite build failed: ${err.message}`);
    process.exit(1);
  }
}

if (require.main === module) main();

module.exports = { extractInner, extractViewBox, namespaceIds, buildSprite, main };
